'use client'

import { useState } from 'react'
import { ChevronDown, Search } from 'lucide-react'

const chapters = [
  {
    title: 'Start with the basics: what your tank does',
    summary: 'Understand the storage system before deciding what to inspect or clean.',
    sections: [
      { heading: 'Why stored water needs attention', paragraphs: ['A storage tank is a buffer between the supply line and the taps in your home. It can make water available when supply is intermittent, but it also means water may sit still for hours or days. During that time, dust can enter through an uncovered opening, sediment can settle at the bottom, and small defects can go unnoticed. A closed tank is not automatically a clean tank; it still needs occasional inspection and maintenance.', 'The exact risks depend on the source water, plumbing, tank material, temperature, location, condition of the cover and how often the stored water is used. A recently cleaned tank connected to a well-maintained supply is different from an older tank exposed to construction dust or a loose access lid. Use the advice here as a practical starting point, not as a substitute for local water-quality guidance or a laboratory test when one is needed.'], checklist: ['Know which tank supplies which taps.', 'Find the safe access point and the person responsible for it.', 'Keep service and repair details in one place.'] },
      { heading: 'The parts worth knowing', paragraphs: ['Most household systems have a tank body, an access lid, an inlet pipe, an outlet, an overflow and one or more vents. Some have a float valve, pump, drain point, level indicator or filtration equipment. Underground sumps may connect to an overhead tank through a pump. Knowing the basic route helps you describe a problem accurately without dismantling anything.', 'You do not need to open fittings or climb onto a roof to learn how the system works. Ask the building manager or a qualified technician to identify the tank, its capacity, the source feeding it and the valves that should not be adjusted. A simple sketch or a few photographs taken from a safe position can make future maintenance conversations much clearer.'], checklist: ['Record the tank type and approximate capacity.', 'Ask which valves control supply and pumping.', 'Leave electrical, pump and plumbing work to qualified people.'] },
      { heading: 'A practical way to use this guide', paragraphs: ['Start with the monthly checks, then read the sections that match your property: overhead tanks, underground sumps, seasonal weather or shared buildings. Keep a short log rather than trying to remember every detail. If you notice a sudden smell, colour change, visible film, leak or damaged cover, treat that as a reason to investigate promptly instead of waiting for the next routine date.', 'Some signs are easy to observe from the outside; others require a trained person to inspect the tank safely. Never enter a tank or place your head inside an opening. Confined spaces can contain dangerous air, and wet ladders, roof edges and electrical equipment add further risk. The useful household role is to notice, record and report—not to perform hazardous work.'], checklist: ['Observe from a safe, accessible location.', 'Write down what changed and when it began.', 'Ask for professional help when the task involves height or entry.'] },
    ],
  },
  {
    title: 'Build a sensible inspection and cleaning schedule',
    summary: 'Use a repeatable rhythm, then adjust it to real conditions.',
    sections: [
      { heading: 'Make routine checks small and regular', paragraphs: ['A brief visual check every month or two is easier to maintain than a complicated inspection that never happens. From a safe position, look for a secure lid, damaged mesh, obvious leaks, damp patches, unusual debris near an opening and changes in the water you can observe without entering the tank. The point is to notice change early, not to certify that water is safe by sight.', 'A household may choose a reminder linked to a regular event such as the first weekend of each month. In an apartment, ask who owns the responsibility and whether building maintenance already keeps a schedule. Do not open a shared tank without permission. A consistent, documented check helps residents distinguish a new issue from a long-standing one and helps technicians prepare for a service visit.'], checklist: ['Choose a recurring date that is easy to remember.', 'Note “normal” conditions so changes stand out.', 'Coordinate access with the owner or building manager.'] },
      { heading: 'Choose cleaning frequency based on evidence', paragraphs: ['There is no single interval that fits every tank, source and building. Many households use a professional inspection or cleaning roughly twice a year as a planning baseline, then adjust according to source-water quality, sediment, usage, tank condition and local recommendations. A written schedule is a prompt to review the tank, not a reason to ignore visible contamination or to clean unnecessarily when a qualified inspection says otherwise.', 'Ask the service provider what they found and why they recommend a particular interval. A tank with a sound cover and low sediment may need a different plan from a tank near construction, with frequent tanker deliveries or a history of debris entering through the vent. If your local authority, property manager or water provider publishes a more specific schedule, follow that guidance for your circumstances.'], checklist: ['Set a baseline date and review it after each service.', 'Use observed condition and supply changes to adjust timing.', 'Do not rely on a calendar alone when something looks wrong.'] },
      { heading: 'Keep a simple maintenance record', paragraphs: ['A useful record can be only a few lines: date, tank or building served, source, what was observed, work completed and any follow-up requested. Save the receipt, service report or before-and-after photographs supplied by the technician. For shared systems, record who approved access and which residents were notified about a temporary interruption.', 'Over time, these notes can show patterns: sediment returning quickly, a cover that repeatedly shifts, a pump that struggles after rain, or a service interval that no longer matches the building’s needs. Records are especially valuable when staff or residents change. They also help you explain the situation without guessing, which makes a future inspection more efficient.'], checklist: ['Keep dates and findings together.', 'Record repairs and open follow-up items.', 'Store the log where the next responsible person can find it.'] },
    ],
  },
  {
    title: 'Recognize changes in water early',
    summary: 'Understand what sight, smell and taste can—and cannot—tell you.',
    sections: [
      { heading: 'Look for changes, not just dramatic problems', paragraphs: ['Water that suddenly looks cloudy, has visible particles, develops a film or changes colour deserves attention. Compare it with what is normal for your supply and ask whether the change is limited to one tap or appears across the building. A single fixture may have an aerator or pipe issue; a change at many taps may point to a broader supply or storage concern.', 'A visual check is only a first clue. Clear water can still contain microorganisms or chemicals that cannot be seen, smelled or tasted, and cloudy water does not identify a specific cause. Do not use appearance alone to declare water safe or unsafe. If there is a public advisory, follow it. If the change is unexplained or persistent, contact the water provider, building manager or a qualified water-testing professional.'], checklist: ['Compare more than one tap when it is safe to do so.', 'Note when the change began and whether it is constant.', 'Do not treat clear appearance as proof of safety.'] },
      { heading: 'Take new odours or tastes seriously', paragraphs: ['A new earthy, musty, metallic, chemical or otherwise unusual smell or taste can have several causes, including plumbing, supply changes, storage conditions or nearby work. Describe the change plainly rather than trying to diagnose it. If other residents notice it too, share that information with the building manager or supplier; a common pattern can help narrow the investigation.', 'When the water is intended for drinking and you suspect contamination, use a known-safe alternative while you seek advice. Follow any official boil-water or do-not-use notice exactly; boiling does not remove every chemical contaminant. Do not add bleach, cleaners or other chemicals to a household tank unless a qualified authority gives instructions for that specific system and purpose.'], checklist: ['Record the smell or taste in neutral terms.', 'Use an alternative safe source if contamination is suspected.', 'Follow official advisories rather than social-media guesses.'] },
      { heading: 'Know when testing is the next step', paragraphs: ['If an issue persists, affects multiple homes or returns after cleaning, ask whether a water test is appropriate. A test should be selected for the concern and collected according to the laboratory’s instructions. A random strip or a sample handled in an unclean container may not answer the question you actually have.', 'A tank-cleaning visit and a water-quality test are different services. Cleaning can remove visible sediment and deposits from accessible surfaces, but it cannot establish that water meets a particular drinking-water standard. Ask for the test provider’s scope, sample location, date and interpretation. If a test identifies a concern, follow the laboratory, water authority or public-health professional’s recommendations for treatment and retesting.'], checklist: ['Ask what the test measures and where samples are taken.', 'Use the laboratory’s clean sampling instructions.', 'Keep the written result with your maintenance record.'] },
    ],
  },
  {
    title: 'Keep lids, vents and openings secure',
    summary: 'A well-fitted cover is one of the simplest barriers against avoidable debris.',
    sections: [
      { heading: 'Check the full opening system', paragraphs: ['A lid should sit securely and remain in place during ordinary weather and routine use. Look from a safe position for gaps, cracks, warping, missing fasteners or evidence that the cover has shifted. A cover that seems closed but leaves a wide gap may still allow dust, insects or small animals to reach the stored water.', 'Vents and overflow pipes need attention too. They should be arranged so air and excess water can move as designed, while screens or guards remain intact where fitted. Do not block an overflow to keep pests out; that can create a leak or flooding problem. If a fitting is missing, loose or incorrectly sized, ask a qualified technician to assess and repair it.'], checklist: ['Check the lid, vent and overflow—not only the lid.', 'Do not block pipes or make improvised sealed covers.', 'Report damaged mesh or loose fittings promptly.'] },
      { heading: 'Reduce contamination around the tank', paragraphs: ['Keep the area around an access point orderly. Avoid storing paint, fuels, pesticides, cleaning concentrates or unrelated tools where they could spill into an opening. Clear loose leaves and rubbish from the exterior when it can be done safely, and keep the access route usable for a future service visit.', 'Nearby construction, roof repairs, bird activity or storm damage may change the amount of debris around a tank. After such work, request a safe inspection rather than assuming that a closed lid remained undisturbed. If you see evidence of animal access or a foreign substance inside, keep people away from the opening and seek professional advice about the appropriate response.'], checklist: ['Keep chemicals and unrelated materials away from access points.', 'Recheck the cover after roof or construction work.', 'Do not retrieve objects by reaching into the tank.'] },
      { heading: 'Avoid well-meant but risky modifications', paragraphs: ['A piece of cloth, loose board or improvised plastic sheet is not a reliable long-term tank cover. It may blow away, trap moisture, obstruct an overflow or make inspection harder. Likewise, a fine screen added without understanding the airflow or pipe arrangement can restrict a vent. Use compatible parts designed for the tank and have repairs completed by someone who understands the system.', 'If the tank is difficult to access, the answer is not to climb a makeshift ladder or stand on a fragile roof. Ask the property owner or service provider to plan safe access. The cost and time involved in a proper repair are usually easier to manage than damage caused by an unsafe improvisation.'], checklist: ['Use purpose-made, compatible covers and fittings.', 'Avoid blocking vents, drains or overflow routes.', 'Arrange safe access before any work begins.'] },
    ],
  },
  {
    title: 'Overhead tanks: rooftop and loft considerations',
    summary: 'Pay attention to sun, weather, roof access and the plumbing connection.',
    sections: [
      { heading: 'Observe from a safe place', paragraphs: ['Overhead tanks may sit on a roof, terrace or loft, where heat, wind and weather can affect the cover and surrounding fittings. Residents should check only from a safe, approved route. A roof edge, wet surface, loose ladder, fragile canopy or nearby electrical line is a reason to stop and ask for help, not an invitation to get a closer look.', 'From a safe point, look for signs such as a shifted lid, water around the tank base, a leak on the ceiling below or a pump that cycles unusually often. Do not step onto the tank, its platform or pipework. A tank may look sturdy but not be designed to support a person. Report observations to the property manager so a trained person can inspect the structure and connections.'], checklist: ['Never climb or walk on a tank.', 'Stop if the roof or access route is wet or unstable.', 'Report leaks below the tank as well as at the tank.'] },
      { heading: 'Understand the pump and float valve', paragraphs: ['An overhead tank often fills through a pump and float valve. If the pump runs continuously, fails to start, makes a new noise or the tank overflows, the issue may involve a valve, electrical control, pipe or supply—not simply a dirty tank. Note what happens and when, then ask a qualified plumber or electrician to inspect the relevant equipment.', 'Do not open electrical panels or adjust a pump while standing in water or near wet fittings. Avoid changing valve positions unless the responsible technician has shown you which control is safe to use. A short description of the symptom, such as “overflow began after the pump was replaced,” can be more useful than an attempted repair.'], checklist: ['Note pump behaviour without touching electrical parts.', 'Mention recent plumbing or power work.', 'Keep children away from roof equipment and access ladders.'] },
      { heading: 'Plan for heat and weather', paragraphs: ['Sun exposure can warm the tank and may age some covers or fittings faster. Ask the installer or tank manufacturer whether a shade, protective coating or replacement part is suitable for your specific material and location. Do not wrap the tank in an unapproved material that traps heat, blocks ventilation or interferes with inspection.', 'Before heavy rain or strong winds, check that a safe inspection is scheduled and that the cover is secure. After a storm, look for visible damage from the ground or another safe location. If there is a structural concern, keep clear and contact building maintenance. Weather preparation should protect both the tank and the people responsible for maintaining it.'], checklist: ['Follow the manufacturer’s advice for sun protection.', 'Check cover security before and after severe weather.', 'Keep roof work within a safe, approved plan.'] },
    ],
  },
  {
    title: 'Underground sumps and ground-level tanks',
    summary: 'These systems have distinct access, drainage and confined-space risks.',
    sections: [
      { heading: 'Treat access covers as a serious hazard', paragraphs: ['A sump cover may be heavy, slippery, level with a driveway or located where vehicles and pedestrians pass. Do not lift it without authorization and a safe method. An open sump can create a fall hazard, and the air inside may be unsafe to breathe. Keep people and pets away from an exposed opening while the responsible team secures the area.', 'Never climb down a ladder into a sump, even if it appears shallow or recently aired out. Confined-space work requires training, equipment, atmospheric checks and a rescue plan. A household member should not attempt entry to retrieve an object or assist someone who has fallen in; call emergency services and qualified responders.'], checklist: ['Keep covers closed and the area clear.', 'Never enter a sump or lean over an opening.', 'Treat an unsecured cover as an urgent access hazard.'] },
      { heading: 'Watch for water ingress and surface runoff', paragraphs: ['Ground-level tanks can be affected by nearby drainage, flooding, leaks or runoff from the surrounding area. Look for persistent dampness, erosion, a damaged joint or water pooling near the cover, but observe from a safe distance. If floodwater may have reached an opening, assume the system needs professional assessment before normal use resumes.', 'Do not pump out, disinfect or refill an affected tank based on an improvised formula. The proper response depends on the material that entered, the system design and local guidance. Contact the building manager, water provider or a qualified service company and explain the timeline, water level and any visible damage.'], checklist: ['After flooding, report possible ingress before using the supply.', 'Keep electrical equipment away from standing water.', 'Follow a qualified assessment before returning the tank to service.'] },
      { heading: 'Coordinate sump and overhead maintenance', paragraphs: ['Where a sump feeds an overhead tank, one component can affect the other. Sediment in the sump may move through a pump or pipe; work on one tank can affect the availability of the whole building’s supply. Ask the service team to identify which tanks, pumps and valves are included before booking.', 'For a shared property, arrange a suitable time, give residents notice and identify a contact person who can approve access. Confirm which outlets may be unavailable and how the team will communicate when service is complete. Clear coordination makes it less likely that someone restarts a pump or opens a valve before the technician is ready.'], checklist: ['List all connected tanks and pumps.', 'Notify affected residents before scheduled work.', 'Confirm who will authorize restarting the system.'] },
    ],
  },
  {
    title: 'Supply sources: municipal, borewell and tanker water',
    summary: 'Different sources can create different maintenance patterns.',
    sections: [
      { heading: 'Municipal or piped supply', paragraphs: ['A piped supply may change temporarily during repairs, flushing or pressure fluctuations. If a notice is issued, follow the supplier’s instructions about use and flushing. When a change appears only after a supply interruption, note the timing and ask the provider whether work occurred nearby. A tank inspection may be helpful, but the issue could also be in the incoming main or building plumbing.', 'Avoid assuming that every change in water quality originates in the storage tank. Ask neighbors whether they have noticed the same change and compare information with the water supplier. If a building has filters or treatment devices, check their service records and ask a technician whether they need inspection. Keep separate notes for supply notices, filter changes and tank maintenance.'], checklist: ['Save supplier notices about planned interruptions.', 'Ask nearby users if they noticed the same change.', 'Track filter maintenance separately from tank cleaning.'] },
      { heading: 'Borewell or locally managed sources', paragraphs: ['A borewell’s characteristics can vary with location, season, pumping depth and maintenance. Household observations cannot determine mineral, chemical or microbiological quality. If the source is private or locally managed, ask who is responsible for testing and what parameters are relevant to your area. Use qualified laboratories and follow the instructions for collecting a sample.', 'A change in pump performance, new sediment or an unusual taste may be associated with the source, the storage tank or the plumbing. Document the change and consult the responsible operator rather than trying to correct it by adding chemicals. A tank cleaning may address deposits on accessible surfaces, but it does not replace testing or source maintenance.'], checklist: ['Know who maintains and tests the source.', 'Use a qualified lab when testing is needed.', 'Do not add treatment chemicals without site-specific instructions.'] },
      { heading: 'Tanker deliveries and shared filling points', paragraphs: ['If water arrives by tanker, record delivery dates and the supplier information available to you. Ask the building manager how deliveries are checked and whether the tank is closed during filling. A delivery can be a useful clue when investigating a sudden change, but a timestamp alone does not prove the source or cause.', 'For multi-home properties, residents should agree on one person to communicate with suppliers and service teams. Keep delivery and cleaning records in the same log so patterns are easier to review. If a supplier provides documentation or a quality statement, store it with the building records and verify what it actually covers.'], checklist: ['Record delivery dates and supplier details.', 'Keep the tank protected during filling.', 'Share concerns through the building’s designated contact.'] },
    ],
  },
  {
    title: 'Seasonal care: monsoon, heat and cold weather',
    summary: 'Weather can change access conditions and expose weak fittings.',
    sections: [
      { heading: 'Before and after heavy rain', paragraphs: ['Rainy weather can make roofs, ladders and tank platforms slippery. Do not schedule a risky inspection simply because the calendar reminder arrived. Look from a safe location for water pooling, a shifted cover, damp walls or signs that runoff reached an access point. Report suspected ingress to the building manager and ask for a professional assessment.', 'Before the rainy season, a qualified person can check that covers, vents, overflows and drainage are in good condition. After flooding, treat possible contamination seriously and follow local authority or water-provider guidance. Do not rely on visual clarity to decide that water is safe after floodwater has entered a tank or supply line.'], checklist: ['Prioritize safe access over a routine date.', 'Check drainage and cover condition before storm season.', 'Escalate suspected floodwater entry promptly.'] },
      { heading: 'During hot, dry periods', paragraphs: ['Heat may increase water use, make a tank area uncomfortable and affect some materials. Do not leave a tank lid open to “air it out.” Instead, keep the cover secured and ask the manufacturer or installer about appropriate sun protection. If water sits unused for longer than usual, discuss the system with a qualified technician rather than applying an unverified treatment.', 'A sudden increase in water demand can make a pump run more often or expose leaks that were previously hard to notice. Note changes in refill patterns and ask building maintenance to check the system. Avoid touching hot pumps, exposed wiring or valves you have not been trained to operate.'], checklist: ['Keep covers secure even in hot weather.', 'Report unusual pump activity or water loss.', 'Use manufacturer-approved protective materials only.'] },
      { heading: 'After repairs or nearby construction', paragraphs: ['Roof, plumbing or construction work can displace a cover, loosen a connection or introduce dust near an opening. Ask the contractor and building manager what was disturbed and whether the tank was protected during work. Arrange a safe inspection when the job is finished, especially if the lid or pipework was removed.', 'If workers used chemicals, coatings or solvents nearby, identify the product and share that information with the responsible professional if a spill or exposure is suspected. Do not rinse unknown materials into a drain or tank. A precise record of the work date and products can help a qualified person decide which assessment is appropriate.'], checklist: ['Ask whether the cover or plumbing was moved.', 'Record work dates and known materials.', 'Request a post-work inspection when access was affected.'] },
    ],
  },
  {
    title: 'Prepare your home or building for a service visit',
    summary: 'Good preparation improves access and reduces surprises.',
    sections: [
      { heading: 'Share useful information at booking', paragraphs: ['When contacting a service team, share the area, tank type, approximate capacity, number of tanks and whether access is through a roof, utility room or shared area. Mention any known leaks, damaged covers, unusual odours, supply changes or previous work. You do not need to diagnose the issue; a clear description helps the provider plan the right equipment and ask follow-up questions.', 'For an apartment or commercial property, identify who can authorize entry and who will be present. Confirm the visit window, parking or loading arrangements, any building rules and how residents will receive updates. If a person has mobility or access needs, tell the coordinator in advance so the service plan can account for them.'], checklist: ['Describe what you know and what you observed.', 'Confirm authority and access for shared spaces.', 'Agree on how timing changes will be communicated.'] },
      { heading: 'Plan household water use', paragraphs: ['Ask the service provider how the visit may affect water availability and how long an interruption could last. The answer depends on the system, tank capacity, number of tanks and work required. Use the provider’s instructions rather than assuming every job follows the same sequence. Make a household plan for essential water use while work is underway.', 'If you keep a small amount of water aside, use clean, suitable containers with secure covers and follow local advice for safe storage. Do not use containers that held chemicals or unknown substances. Keep stored water away from children, pets and cleaning products, and use it only for the intended purpose.'], checklist: ['Ask about likely interruption and restart timing.', 'Use clean, covered containers if temporary storage is needed.', 'Keep temporary containers separate from chemical products.'] },
      { heading: 'Make the work area ready', paragraphs: ['Clear loose items from the access route if it is safe to do so. Secure pets, notify residents, and keep children away from ladders, tools and open access points. Do not move heavy covers or disconnect plumbing yourself unless the technician has specifically instructed you and you can do so safely.', 'A designated adult contact can answer questions and approve the agreed scope. Before work begins, ask the team to explain what they plan to do, which tanks are included, and how they will protect the surrounding area. If the proposed work differs from the booking or an unexpected issue appears, pause and confirm the plan before proceeding.'], checklist: ['Clear the route without entering hazardous areas.', 'Keep bystanders away from equipment and openings.', 'Confirm scope and any added work before it starts.'] },
    ],
  },
  {
    title: 'What a professional cleaning visit may involve',
    summary: 'Know the broad stages, while remembering every system is different.',
    sections: [
      { heading: 'Assessment and setup', paragraphs: ['A responsible team should first confirm the tanks and scope, assess safe access and identify any visible concerns. They may ask about supply source, recent changes, water availability or previous maintenance. If access is unsafe or the structure appears damaged, the appropriate response may be to stop and recommend a repair or specialist assessment rather than proceed.', 'Before work begins, confirm how the team will manage nearby surfaces, tools, water and waste. Ask what the quoted service includes and what is outside the scope. Cleaning, plumbing repair, structural repair, disinfection, water testing and pump servicing may be separate tasks. A clear agreement helps avoid misunderstandings and makes the final report more useful.'], checklist: ['Confirm which tanks are included.', 'Ask what the quoted service covers.', 'Do not pressure a team to work in unsafe conditions.'] },
      { heading: 'Cleaning, rinsing and observations', paragraphs: ['Depending on the tank and service scope, a team may remove remaining water, collect settled debris, clean accessible surfaces, rinse and inspect visible fittings. The methods and products should be suitable for the tank material and intended use. Ask the provider to explain the process in plain language, especially if you have concerns about residues or the system’s finish.', 'A cleaning visit can reveal issues such as a damaged lid, cracked surface, corroded fitting or unusual amount of sediment. Ask the team to distinguish what they observed from what they suspect. Photographs can help document visible conditions, but they do not replace testing when the concern is about water quality that cannot be seen.'], checklist: ['Ask which materials and methods are planned.', 'Request clear notes about visible damage or follow-up.', 'Treat testing as separate unless explicitly included.'] },
      { heading: 'Waste, disinfection and service records', paragraphs: ['Ask how removed water and debris will be handled, particularly in shared buildings or areas with drainage restrictions. Products and procedures should follow the manufacturer’s directions and local requirements. Do not combine chemicals or reuse an unknown container. If you have a product sensitivity or a building rule, raise it before the work starts.', 'At completion, request a summary of work, any observations, parts needing repair and the recommended review date. Confirm who will restart pumps or reopen valves and whether the team has completed its own final checks. Keep the report with your maintenance log and follow any instructions about flushing or returning the tank to normal use.'], checklist: ['Agree on waste handling before work starts.', 'Never mix or improvise cleaning chemicals.', 'Save the report and any follow-up recommendations.'] },
    ],
  },
  {
    title: 'After cleaning: returning the system to normal use',
    summary: 'Follow the technician’s handover and watch for issues as service resumes.',
    sections: [
      { heading: 'Wait for a clear handover', paragraphs: ['Do not assume the tank is ready simply because tools have been packed away. Ask the service team whether the system is ready, whether any flushing or restart sequence is required, which valves or pumps may be operated and whether any temporary restrictions remain. The safe sequence depends on the work completed and system design.', 'If the technician says a repair or test is still pending, make sure the building manager and affected residents know. Keep the access point closed and secure. Do not restart a pump or reconnect a line if the team has isolated it for safety. A clear handover prevents confusion when one person supervises the work and another person manages the building afterward.'], checklist: ['Ask for an explicit “ready to use” handover.', 'Confirm the restart sequence and responsible person.', 'Keep isolation tags or warnings in place until cleared.'] },
      { heading: 'Observe the first use', paragraphs: ['When the system returns to service, follow the provider’s instructions about flushing taps or waiting before use. Watch for leaks, unusual pump noise, low pressure or a persistent change in water appearance. If something seems wrong, stop using the affected outlet if appropriate and contact the service provider or building manager with the details.', 'A short-term change after maintenance may have a straightforward explanation, but do not guess. Ask the team what to expect and how long it should last. If an unusual taste, smell, colour or film continues, use a safe alternative for drinking and seek professional or supplier guidance. Cleaning records and before-and-after notes help the team understand what happened.'], checklist: ['Follow the handover instructions exactly.', 'Check accessible areas for leaks without touching equipment.', 'Report ongoing changes instead of self-treating the water.'] },
      { heading: 'Close the loop in your records', paragraphs: ['Update the maintenance log with the date, tasks completed, visible findings, product or method information the provider supplied, and any repair still required. Keep the receipt and report together. For a shared property, note who accepted the handover and when residents were told that service had ended.', 'Use the findings to adjust the next inspection date, not to create a rigid schedule that ignores new conditions. If sediment returned quickly or the lid was damaged, record the follow-up action and who owns it. A simple reminder with a named responsible person is more reliable than an unassigned note in a group chat.'], checklist: ['Record completion and any pending repair.', 'Assign every follow-up action to someone.', 'Set the next review reminder based on the findings.'] },
    ],
  },
  {
    title: 'Shared buildings, societies and commercial properties',
    summary: 'Clear responsibility and communication matter as much as the cleaning itself.',
    sections: [
      { heading: 'Name a responsible coordinator', paragraphs: ['A shared tank may serve many homes, offices or businesses. Choose one person or role to coordinate the schedule, approve access, keep records and communicate with the provider. Make sure that responsibility is known to residents and has a backup for holidays or staff changes. Without ownership, routine work can be delayed or repeated unnecessarily.', 'The coordinator should maintain a basic inventory: tank locations, approximate capacities, connected areas, access restrictions, pump details and last service dates. Sensitive site information should be shared only with people who need it. For commercial locations, follow facility rules for contractors, permits, visitor sign-in and access to restricted areas.'], checklist: ['Assign a primary and backup contact.', 'Maintain a secure tank and access inventory.', 'Follow site rules for contractor entry.'] },
      { heading: 'Communicate interruptions early', paragraphs: ['Residents and staff need practical notice: when work is expected, which floors or facilities may be affected, what water uses might pause, who to contact and how completion will be confirmed. Avoid promising an exact restart time unless the provider has confirmed it. If work is delayed, send a short update rather than leaving people to infer what is happening.', 'If a building relies on multiple tanks, identify which sections each tank serves. A partial outage may be manageable if residents know where it applies. Do not ask tenants or employees to operate valves or pumps unless they are authorized and trained. Centralizing messages avoids conflicting instructions and reduces the chance that someone interrupts the service process.'], checklist: ['Give a time window and a contact method.', 'Identify affected areas and services.', 'Update the notice if the schedule changes.'] },
      { heading: 'Plan procurement and follow-up', paragraphs: ['Compare providers on scope, safety practices, communication, documentation and suitability for the property—not price alone. Ask whether the quotation includes all listed tanks, waste handling, photographs, repairs or testing. Get exclusions in writing so building management can plan separately for structural, electrical or plumbing work.', 'After each visit, review the report and close outstanding tasks. A cleaned tank with a broken lid still needs a repair plan. Track who approved the expense, who received the report and when follow-up will happen. This simple process builds continuity even when a property changes managers or the committee rotates.'], checklist: ['Compare equivalent scopes, not just headline prices.', 'Separate cleaning from repair and testing tasks.', 'Review unresolved findings at the next management meeting.'] },
    ],
  },
  {
    title: 'Water-saving habits and responsible storage',
    summary: 'Use stored water thoughtfully without compromising system safety.',
    sections: [
      { heading: 'Reduce avoidable waste', paragraphs: ['A leaking float valve, overflowing tank or dripping pipe can waste water and may indicate a maintenance issue. Note when the loss occurs and ask a qualified technician to inspect the system. Do not alter a float valve or pump setting without knowing the design; a small adjustment can affect supply or cause an overflow elsewhere.', 'Households can also reduce demand through ordinary conservation: repair indoor leaks, use water-efficient fixtures where practical and avoid running taps unnecessarily. Conservation does not replace tank cleaning, and it should not lead to storing water in open or unsuitable containers. Keep the tank covered and use approved storage arrangements for any temporary reserve.'], checklist: ['Report overflow and persistent dampness.', 'Use clean, covered temporary containers if needed.', 'Avoid unapproved changes to valves and controls.'] },
      { heading: 'Avoid unsafe storage shortcuts', paragraphs: ['Do not store drinking water in containers that once held fuel, pesticides, cleaners or other chemicals. Choose clean containers intended for water, keep them covered and prevent hands or utensils from contaminating the contents. Follow local guidance for storage duration and handling, especially during emergencies or supply interruptions.', 'Do not pour leftover water, cleaning products or unknown substances into a tank. If a non-water product enters the system, keep people from using the affected supply and seek advice from a qualified authority or water professional. The right response depends on the substance and amount; improvised dilution can spread contamination rather than resolve it.'], checklist: ['Use suitable containers and keep them clean.', 'Separate stored water from chemicals and fuels.', 'Seek qualified advice after any accidental spill.'] },
      { heading: 'Keep conservation separate from treatment', paragraphs: ['Saving water is about reducing unnecessary use; treatment is about addressing a quality or safety concern. One does not substitute for the other. If a supplier issues a use advisory, follow it even if you have a well-maintained tank. If a tank needs cleaning, reducing water use will not remove settled deposits.', 'Likewise, household filters or purifiers have maintenance requirements that differ from storage tanks. Record filter replacement and servicing separately, and ask the manufacturer what the device can and cannot address. Avoid assuming that one device treats every possible contaminant. When in doubt, consult the supplier or a qualified testing professional.'], checklist: ['Track tank service and filter service separately.', 'Follow public advisories for your supply.', 'Check a purifier’s stated scope and maintenance instructions.'] },
    ],
  },
  {
    title: 'Troubleshooting common concerns',
    summary: 'Use observations to guide a safe next step, not a do-it-yourself diagnosis.',
    sections: [
      { heading: 'Water appears cloudy after a supply change', paragraphs: ['A temporary supply interruption, plumbing work or disturbance in a line can change the appearance of water. Note which taps are affected, whether the issue began after a known event and whether it clears according to supplier instructions. Do not assume the tank is the source until the supply and building plumbing have also been considered.', 'If cloudiness persists, affects multiple homes or comes with an unusual smell or taste, stop guessing and contact the water provider or building manager. Use an alternative safe drinking source if contamination is suspected. A sample may be useful, but only collect it if a qualified lab or authority provides the correct container and procedure.'], checklist: ['Record the timing and affected taps.', 'Check supplier notices and building updates.', 'Seek advice if the change persists or is unexplained.'] },
      { heading: 'Pump runs often, pressure drops or water overflows', paragraphs: ['These symptoms can point to a leak, valve issue, changing demand, pump fault or electrical control problem. Note when the symptom occurs and whether it coincides with a supply change or recent repair. A photo or short recording made from a safe distance can help a technician understand the pattern.', 'Do not open an electrical enclosure, place a hand near moving equipment or stand in standing water to investigate. If there is exposed wiring, burning smell, flooding near electrical equipment or a risk of structural damage, keep clear and contact the appropriate emergency or maintenance service.'], checklist: ['Observe from a safe distance and note the pattern.', 'Do not dismantle pumps or electrical controls.', 'Escalate electrical and flooding hazards promptly.'] },
      { heading: 'Sediment returns soon after a clean', paragraphs: ['Repeated sediment may relate to the source, incoming line, tank condition, construction activity or the way the system is operated. Ask the service team to document what they found and whether the sediment’s appearance suggests a need for further assessment. Do not infer a contaminant from colour alone.', 'If the pattern repeats, consider coordinating a source review or appropriately selected water test. Keep delivery, supply and cleaning dates together so the timeline is clear. A cleaning schedule can be adjusted, but recurring deposits may require a repair or source-level solution rather than more frequent cleaning alone.'], checklist: ['Compare service dates with source or supply events.', 'Ask whether testing or plumbing inspection is appropriate.', 'Do not use appearance to identify a specific contaminant.'] },
    ],
  },
  {
    title: 'Choose and work with a service provider',
    summary: 'A clear scope, safe practices and useful documentation build confidence.',
    sections: [
      { heading: 'Ask practical questions before booking', paragraphs: ['Ask what the service includes, which tanks are covered, how access will be managed, what preparation is needed and how the work will be documented. Confirm whether the quote includes inspection, cleaning, disinfection, waste handling, repairs or laboratory testing; these are not automatically the same service. Ask how changes to scope will be approved.', 'A professional provider should be willing to explain its approach in plain language and discuss safety limitations. Be cautious of promises that water is guaranteed safe without a defined test, or of advice to mix household chemicals without a site-specific procedure. Request written confirmation of price, travel charges, exclusions and the contact person for changes.'], checklist: ['Compare written scopes and exclusions.', 'Ask what documentation you will receive.', 'Avoid unsupported guarantees about water quality.'] },
      { heading: 'Confirm site and safety requirements', paragraphs: ['Tell the provider about roof access, locked rooms, shared areas, low headroom, electrical equipment and any known structural defects. Ask who supplies ladders or access equipment and whether the building must arrange a safe platform or permit. If safe access cannot be established, rescheduling is preferable to a rushed or hazardous job.', 'For larger properties, confirm insurance, site induction, contractor registration and working-hour rules as required by the owner. Keep residents away from work areas and establish a communication channel for interruptions. A clear safety plan protects residents and workers and helps the service proceed without avoidable delays.'], checklist: ['Share known hazards before the visit.', 'Follow building access and contractor rules.', 'Stop work if conditions become unsafe.'] },
      { heading: 'Review the handover and report', paragraphs: ['At the end of the job, ask for the tanks serviced, tasks completed, visible findings, limitations and recommendations. If photographs are provided, understand what they show and which tank they correspond to. Ask about any repair or test that remains outstanding and who should arrange it.', 'Keep the report with the property’s records and use it to set follow-up dates. If you are dissatisfied, describe the specific issue and give the provider an opportunity to clarify the scope. A factual service history makes it easier to compare future work and avoid repeating misunderstandings.'], checklist: ['Check the report names the right tanks.', 'Record limitations and unresolved work.', 'Keep communication factual and written where possible.'] },
    ],
  },
  {
    title: 'Tank materials, age and visible wear',
    summary: 'Understand why surface condition and manufacturer guidance matter.',
    sections: [
      { heading: 'Respect the tank material', paragraphs: ['Household tanks may be made from different plastics, metals, concrete or other materials. Each material responds differently to heat, sunlight, cleaning methods and age. A process suitable for one tank may damage another, so the service team should know the manufacturer, model or material whenever that information is available. If you cannot identify it, a photo of the label or exterior can help.', 'Avoid abrasive tools, harsh solvents or unapproved coatings. Scratches, weakened joints and damaged internal finishes can make future cleaning harder or shorten the life of the tank. Ask the manufacturer or a qualified installer which products and replacement parts are compatible. When the tank has no readable label, do not assume that a generic internet recommendation applies to it.'], checklist: ['Photograph the product label from a safe location.', 'Ask which cleaning materials are compatible.', 'Do not apply coatings or sealants without approval.'] },
      { heading: 'Notice aging without attempting a repair', paragraphs: ['Cracks, brittle edges, corrosion, bulging walls, loose joints and recurring dampness may indicate that a tank or fitting needs professional assessment. Some changes are visible from the outside; others require a trained technician. A small leak can also originate in nearby plumbing, so note where water appears rather than concluding which part failed.', 'Do not patch a tank with household glue, tape or a coating unless a qualified professional confirms that the repair is appropriate. A temporary-looking fix can hide a worsening defect or contaminate water. Keep people away from a damaged structure and arrange the right inspection, especially when the tank is elevated or supports other equipment.'], checklist: ['Record the location and approximate size of visible damage.', 'Keep clear of bulging, unstable or leaking structures.', 'Request a repair assessment before cleaning continues.'] },
      { heading: 'Plan replacement before failure', paragraphs: ['A maintenance log can help identify repeated repairs or worsening surface condition. Ask the manufacturer or installer about expected service life, inspection recommendations, replacement parts and signs that the tank should be retired. The answer depends on material, installation, climate, use and maintenance history, not just the date printed on a label.', 'For a shared property, plan replacement as a facilities project. Confirm capacity, access, support structure, connected pipes, permits and expected interruption before ordering a tank. A replacement should be installed by qualified people and checked for leaks, secure covers and compatible connections before normal operation resumes.'], checklist: ['Review recurring repair notes and manufacturer guidance.', 'Confirm structural support and access before replacement.', 'Document commissioning and handover of a new tank.'] },
    ],
  },
  {
    title: 'Pipes, pumps, valves and connected equipment',
    summary: 'A tank is one part of a system; connected equipment deserves its own care.',
    sections: [
      { heading: 'Trace the system at a high level', paragraphs: ['Water may pass through a supply line, storage tank, pump, filter, pressure system and multiple branches before reaching a tap. Knowing this broad path helps you report symptoms: a problem at one tap differs from a change at every outlet, and a pump that cycles constantly may signal a control or leak issue. You can document what you observe without opening or adjusting equipment.', 'Ask a qualified plumber or building technician to label important valves and explain which ones residents may operate. Keep those labels readable and store the diagram with building maintenance records. Do not turn an unknown valve to “see what happens”; it may interrupt supply to other homes, damage equipment or create a leak that is difficult to isolate.'], checklist: ['Keep an approved system diagram if available.', 'Label controls through a qualified technician.', 'Do not operate unfamiliar valves or pump controls.'] },
      { heading: 'Keep maintenance tasks distinct', paragraphs: ['Tank cleaning, filter replacement, pump servicing and plumbing repair are separate tasks even when one visit includes more than one. Each device may have its own manufacturer instructions and maintenance interval. Keep a separate record of filter model and replacement date, pump service and repair work, and tank inspections so one completed task is not mistaken for another.', 'If water quality changes after a filter is installed or serviced, ask the filter provider and water supplier for guidance. A filter has a defined purpose and capacity; it cannot be assumed to remove every possible contaminant. Follow the product instructions for replacement and sanitizing, and do not bypass a device unless the responsible technician directs you.'], checklist: ['Track filters, pumps, pipes and tanks separately.', 'Follow the device manufacturer’s service instructions.', 'Ask what a filter is designed to remove.'] },
      { heading: 'Report leaks and electrical concerns safely', paragraphs: ['A wet patch below a tank, dripping joint, unusual pump sound or pressure drop is useful information for a technician. Note the time, location and whether the symptom is continuous or intermittent. If a leak is near wiring, an electrical panel, a lift shaft or a ceiling that appears unstable, keep away and use the building’s emergency maintenance process.', 'Never touch electrical equipment while standing in water, remove pump covers or use a tool on a live fitting. If there is immediate danger, alert others and contact emergency services or the appropriate site response team. Taking a photo is optional; do not move closer just to capture one. Safety comes before diagnosis or documentation.'], checklist: ['Describe symptoms from a safe location.', 'Keep away from water near electrical equipment.', 'Use the site emergency process for urgent hazards.'] },
    ],
  },
  {
    title: 'Temporary interruptions and emergency water planning',
    summary: 'Prepare calmly for service outages, advisories and supply disruptions.',
    sections: [
      { heading: 'Know the local communication channels', paragraphs: ['Find out how your water supplier, municipality, building manager or housing society communicates planned work and urgent advisories. Save the official contact details and make sure at least one other household member knows where to find them. During an interruption, use the most recent verified notice rather than forwarding an old screenshot whose date or area may not match.', 'If the household includes infants, older adults, people with disabilities or anyone with specific medical water needs, plan ahead with their caregiver or clinician. Do not assume one emergency instruction fits every person. Building managers should make essential notices accessible, identify a contact for questions and update residents when official information changes.'], checklist: ['Save current official contact information.', 'Check date, location and scope on every notice.', 'Consider household members with specific water needs.'] },
      { heading: 'Store a limited reserve safely', paragraphs: ['A clean, covered, food-grade container can be useful during a planned interruption if local guidance recommends keeping a reserve. Use a container intended for drinking water, label it, keep it away from sunlight and chemicals, and follow the authority’s instructions about how long to keep it. Containers previously used for fuels, pesticides or cleaners should never be repurposed for drinking water.', 'For longer disruptions, follow the supplier or public-health authority’s instructions about sourcing and treating water. Do not improvise chemical doses, mix products or assume that boiling resolves every concern. If an advisory says not to use the water for any purpose, follow that notice and use an approved alternative. Keep a written copy of instructions for the people who may be caring for the household.'], checklist: ['Use clean containers intended for drinking water.', 'Label and cover any temporary reserve.', 'Follow current authority guidance for treatment and use.'] },
      { heading: 'Resume service only when instructed', paragraphs: ['After a planned repair or advisory, follow the water supplier’s instructions for flushing, waiting or limiting use. If the building has a tank, ask the responsible manager whether it was isolated, inspected or affected during the interruption. Do not restart a pump or open a valve before the authorized person confirms that the system is ready.', 'If the water looks, smells or tastes different after the supply returns, record the change and contact the supplier or building manager. Where there is doubt about drinking safety, choose another safe source while seeking guidance. Keep the advisory and the service handover in your records so the next maintenance person can understand the sequence of events.'], checklist: ['Use the supplier’s restart instructions.', 'Confirm building equipment is ready before operation.', 'Report unexpected changes after service resumes.'] },
    ],
  },
  {
    title: 'Moving in, moving out and handing over a property',
    summary: 'Make water-storage knowledge part of a useful home handover.',
    sections: [
      { heading: 'Ask the questions that prevent guesswork', paragraphs: ['When moving into a house or apartment, ask where the tank is, which areas it serves, who maintains it, what the supply source is and when it was last inspected or cleaned. Request any service reports, repair notes and water advisories that affect the property. If the seller, landlord or manager does not know, record that as an unknown and arrange an appropriate inspection.', 'Do not open a tank or enter a service area that is locked or unsafe just to check it yourself. Ask for authorized access and a qualified person to explain the system. For tenants, clarify whether the landlord, society or tenant is responsible for routine maintenance and how to report urgent issues. Written responsibility avoids disputes later.'], checklist: ['Ask for the last service date and report.', 'Confirm who is responsible for maintenance.', 'Arrange authorized inspection if important details are unknown.'] },
      { heading: 'Leave clear information for the next person', paragraphs: ['When handing over a home or facility, share the tank location, access contact, supplier details, recent cleaning date, known defects and outstanding appointments. Include practical notes about pumps or valves only if they have been verified by a qualified person. Remove outdated instructions that could cause someone to operate a control incorrectly.', 'For a shared building, update the official maintenance log and notify the responsible manager rather than relying only on a private message. Protect personal information and security details: access codes and keys should be passed through approved channels. A concise handover lets the next occupant maintain the system without making assumptions or repeating avoidable work.'], checklist: ['Update the shared maintenance log.', 'Pass access details through secure channels.', 'Mark uncertain or unverified system notes clearly.'] },
      { heading: 'Revisit the plan after changes', paragraphs: ['A new occupant, renovation, change in water source or alteration to the plumbing may change the maintenance plan. Ask whether the tank capacity and supply path still match the property’s use. After construction, confirm that covers and fittings remain secure and that any removed filters or pipes were reinstalled correctly by qualified workers.', 'A new building manager should review the log, identify overdue repairs and confirm who can authorize service. Small administrative steps—one current contact list, one schedule and one shared record—reduce the chance that tank maintenance disappears during a transition.'], checklist: ['Review the plan after renovation or supply changes.', 'Update contacts and authorization roles.', 'Schedule a safe inspection when system history is unclear.'] },
    ],
  },
  {
    title: 'Safety and communication for everyone at home',
    summary: 'Make tank maintenance understandable and safe for the people who share the space.',
    sections: [
      { heading: 'Keep children and pets away from work zones', paragraphs: ['Open covers, hoses, ladders, wet floors and tools can create hazards during a cleaning visit. Tell children and visitors which areas are off limits, and keep pets in a separate secure space. Do not ask a child to fetch an item or look into a tank, even when an adult is nearby.', 'For shared properties, use the building’s usual barriers or notices to keep residents away from active work. If a cover must be open, the responsible crew should secure the area continuously and close it as soon as practical. Report an unsecured opening immediately; do not try to move a heavy cover alone.'], checklist: ['Set a clear boundary around the work area.', 'Keep children and pets supervised and away.', 'Report an open or unguarded tank access point.'] },
      { heading: 'Make instructions accessible to the household', paragraphs: ['A water interruption notice is most useful when it reaches everyone who needs it. Use plain language, identify affected areas, include a time window and name a contact for questions. Consider residents who rely on accessible formats, do not use the building’s main messaging app or need assistance carrying water.', 'In a household with caregiving responsibilities, share relevant timing and instructions directly with the people who will be present. If anyone has a health-related need for water, ask their care professional or the responsible authority how to plan. Do not make individual medical decisions based on a general maintenance notice.'], checklist: ['Use clear, dated, easy-to-share messages.', 'Provide a contact route beyond one group chat.', 'Coordinate specific health needs with the right professional.'] },
      { heading: 'Use one clear point of contact', paragraphs: ['During service, one designated adult or building contact should relay questions between residents and technicians. This reduces the chance that several people give conflicting instructions about access, pumps or restart timing. The contact should know the approved scope and who can authorize extra work.', 'After the visit, send a short completion note that states what was serviced, whether any restrictions remain and who owns follow-up. Keep the provider’s report available for residents or future managers who need it. Avoid sharing private access codes or personal contact details more widely than necessary.'], checklist: ['Name a contact before work begins.', 'Confirm who can approve a change in scope.', 'Share service updates without exposing private access details.'] },
    ],
  },
  {
    title: 'Frequently asked questions',
    summary: 'Short answers to common household and building-management questions.',
    faqs: [
      ['How often should a household tank be cleaned?', 'There is no universal interval for every source and tank. Many households use roughly six months as a planning reminder, then adjust for local guidance, visible sediment, water-source changes, tank condition and professional inspection findings. A calendar date should not replace attention to new signs or a water-provider advisory.'],
      ['Does clear water mean it is safe to drink?', 'No. Some concerns cannot be seen, smelled or tasted. Appearance can help you notice a change, but it cannot establish microbiological or chemical quality. If you need to confirm safety, follow official guidance and use a qualified laboratory or water authority to select and interpret an appropriate test.'],
      ['Can I clean the tank myself?', 'Only tasks that can be done safely from an approved location should be considered by residents. Tank entry, roof work, electrical equipment, heavy covers and chemical treatment require appropriate training and controls. Never climb into a tank or enter a sump. Use a qualified provider for hazardous or specialist work.'],
      ['Should I add bleach to the tank?', 'Do not add bleach or another chemical based on a generic online dose. Correct products and procedures depend on tank size, material, water use, concentration and local requirements. Follow instructions from a qualified authority or service professional for your specific system, and never mix cleaning products.'],
      ['What should I do if water smells unusual?', 'Note when it began, which taps are affected and whether other residents notice it. If contamination is suspected, use an alternative safe source for drinking while contacting the supplier, building manager or qualified professional. Do not try to hide the smell by adding fragrance or chemicals.'],
      ['What if the water changes after a supply shutdown?', 'Check whether the supplier issued a notice and follow its flushing or use instructions. Record the timing and whether one or several taps are affected. If the change persists, contact the supplier or building manager. A tank is one possibility, but the incoming main or plumbing can also be involved.'],
      ['Is tank cleaning the same as water testing?', 'No. Cleaning addresses accessible deposits and the condition of the tank within the agreed scope. Testing measures selected water-quality parameters using a sample. A clean-looking tank does not prove a sample meets a standard, and a test does not repair a damaged lid or fitting.'],
      ['Does a water purifier replace tank maintenance?', 'No. A purifier and a storage tank have different roles and maintenance needs. Check the device manufacturer’s stated scope, servicing schedule and limitations. Keep records for filters and tanks separately, and follow any supplier or public-health advice about the water source.'],
      ['Can I block a vent to keep insects out?', 'Do not block a vent or overflow. These openings are part of the system design, and obstructing them can create pressure, leakage or other problems. Ask a qualified technician to fit a compatible screen or repair a missing or damaged guard.'],
      ['What should happen after flooding near a sump?', 'Keep people away from the opening and report possible water ingress to the building manager or water provider. Do not assume the supply is safe because it looks clear, and do not enter or treat the tank yourself. Follow qualified assessment and local guidance before returning it to normal use.'],
      ['How do I prepare for a service visit?', 'Share tank type, approximate capacity, access details, number of tanks and any known changes or defects. Confirm the scope, timing, expected interruptions, resident communication and who will approve extra work. Keep children and pets away from equipment and access points during the visit.'],
      ['What if sediment returns quickly?', 'Keep the service report and note when sediment reappears. Ask whether the source, incoming line, tank condition or nearby work should be reviewed. Repeated cleaning may not address a source problem. A qualified professional can advise whether inspection, repair or selected water testing is appropriate.'],
      ['Can I enter a tank if it is empty?', 'No. An empty tank is still a confined space and may contain unsafe air, slippery surfaces or other hazards. Entry requires trained personnel, appropriate equipment, atmospheric checks and a rescue plan. Never enter to retrieve an object or help someone who has fallen inside.'],
      ['Should the overhead and underground tank be cleaned together?', 'That depends on how the building is plumbed and what the service provider finds. If one tank feeds another, ask the provider to review the whole connected system and explain what is included. Coordinating work can reduce repeated interruptions, but the scope should be confirmed for each tank.'],
      ['Do I need to store water before a visit?', 'Ask the service provider whether and when supply may be interrupted. If temporary storage is useful, use clean containers intended for water, keep them covered and follow local storage guidance. Avoid chemical containers and keep water away from cleaners, fuels and other contaminants.'],
      ['Who should manage tank maintenance in an apartment?', 'The owner, housing society, facility manager or another designated role should be clearly responsible. Name a primary contact and backup, keep service records, notify residents and coordinate access. Residents should report issues but should not open or alter shared tanks without authorization.'],
      ['What details should I keep in a tank log?', 'Record the tank location and capacity if known, source, inspection and service dates, observations, repairs, provider reports and unresolved follow-up. For shared buildings, note resident notices and the person who accepted the handover. Keep the record accessible to the next responsible manager.'],
      ['Can photos prove that water is safe?', 'No. Photos can document visible conditions and help track changes, but they cannot identify every contaminant or establish compliance with a water-quality standard. Use an appropriate test and expert interpretation when safety confirmation is needed. Keep photographs as supporting maintenance records, not as a substitute for testing.'],
      ['What if a technician finds a damaged tank?', 'Ask the technician to describe the visible damage, explain whether it affects safe operation and recommend the appropriate repair specialist. Cleaning may need to pause until a structural, plumbing or electrical issue is resolved. Keep the area secured and communicate any use restrictions to affected residents.'],
      ['Where can I get advice specific to my area?', 'Contact the local water supplier, public-health or municipal authority, building manager, tank manufacturer or a qualified water-testing professional. Requirements and source conditions vary by location. Share the tank type, supply source, observed change and service history so the advice is relevant to your system.'],
      ['Should the tank hatch stay open between visits?', 'No. Keep the access cover securely closed and use compatible fittings for designed vents and overflows. An open hatch can allow debris or pests into the tank and create a fall hazard. If a cover is damaged, arrange a safe repair rather than leaving it propped open.'],
      ['Can a visual inspection detect every contamination concern?', 'No. A visual inspection can identify visible changes or damage, but it cannot confirm microbiological or chemical quality. Use observations to decide when to ask for professional advice. If confirmation is needed, use a qualified laboratory or authority to select and interpret a suitable test.'],
      ['Who should turn the pump or water supply back on?', 'The person designated by the service team or building manager should follow the confirmed restart instructions. Do not operate a pump or valve that has been isolated for the work unless you are authorized and trained. Confirm that the provider has handed the system back before resuming normal operation.'],
      ['What should I tell the team if someone needs accessible arrangements?', 'Share access needs and the best contact method before the appointment, while limiting personal details to what the coordinator needs. Ask the provider to explain any interruption in a clear format and plan around the person who will be present. For medical needs, confirm the plan with their care professional.'],

    ],
  },
]

export function GuideLibrary() {
  const [query, setQuery] = useState('')
  const filteredChapters = chapters.filter((chapter) => {
    const content = `${chapter.title} ${chapter.summary} ${chapter.sections?.flatMap((section) => [...section.paragraphs, ...section.checklist]).join(' ') ?? ''} ${chapter.faqs?.flat().join(' ') ?? ''}`
    return content.toLowerCase().includes(query.trim().toLowerCase())
  })

  return <div className="guide-library">
    <div className="guide-library-intro">
      <div><span className="eyebrow">THE PRACTICAL HANDBOOK</span><h2>Tank care, from everyday checks to service day.</h2><p>A long-form reference for homeowners, tenants, facility managers and housing societies. Browse the chapters or search for a topic that matches what you’re seeing.</p></div>
      <label className="guide-search"><Search size={17} aria-hidden="true"/><span className="sr-only">Search the tank care guide</span><input type="search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search the guide"/></label>
    </div>
    <details className="guide-toc" open={Boolean(query)}>
      <summary><span className="guide-toc-title">Browse all chapters</span><span className="guide-toc-count">{query ? `${filteredChapters.length} matching chapters` : `${filteredChapters.length} chapters`}</span><ChevronDown className="guide-toc-chevron" size={18} aria-hidden="true"/></summary>
      <nav className="guide-table-of-contents" aria-label="Guide chapters">{filteredChapters.map((chapter, index) => <a href={`#guide-chapter-${index + 1}`} key={chapter.title}><span>{String(index + 1).padStart(2, '0')}</span>{chapter.title}</a>)}</nav>
    </details>
    <div className="guide-chapters">{filteredChapters.map((chapter, index) => <details className="guide-chapter" id={`guide-chapter-${index + 1}`} key={chapter.title} open={index === 0 && !query}>
      <summary><span className="guide-chapter-number">CHAPTER {String(index + 1).padStart(2, '0')}</span><span className="guide-chapter-title">{chapter.title}</span><span className="guide-chapter-summary">{chapter.summary}</span><ChevronDown className="guide-chapter-chevron" size={19} aria-hidden="true"/></summary>
      <div className="guide-chapter-body">{chapter.sections?.map((section) => <section className="guide-topic" key={section.heading}><h3>{section.heading}</h3>{section.paragraphs.map((paragraph) => <p key={paragraph}>{paragraph}</p>)}{section.checklist && <ul>{section.checklist.map((item) => <li key={item}>{item}</li>)}</ul>}</section>)}{chapter.faqs?.map(([question, answer]) => <section className="guide-faq" key={question}><h3>{question}</h3><p>{answer}</p></section>)}</div>
    </details>)}</div>
    {!filteredChapters.length && <p className="guide-empty-state">No guide chapters match that search. Try a different word or phrase.</p>}
    <p className="guide-disclaimer">This handbook offers general household information, not a water-quality certification or a substitute for local authority guidance. Follow your supplier’s advisories and use qualified professionals for testing, repairs, chemical treatment, roof access and confined-space work.</p>
  </div>
}
